update ntss.sys_data_set set sql = ' SELECT
 ( o ->> ''Rp'' ) AS rp, --RP番号
 ( o ->> ''unchg'' ) AS unchg, --unchg
 ( o ->> ''type'' ) AS type, --type
 ( o ->> ''F1'' ) AS f1, --F1
 ( o ->> ''F2'' ) AS f2, --F2
 ( o ->> ''F3'' ) AS f3, --F3
 ( o ->> ''F4'' ) AS f4, --F4
 ( o ->> ''F5'' ) AS f5, --量
 ( o ->> ''F6'' ) AS f6, --単位 
 ( o ->> ''R'' ) AS r,   --薬剤名称
 to_date(op.issue_date, ''YYYYMMDD'') issue_date,--交付日
 to_date(op.expiration_date, ''YYYYMMDD'') expiration_date, --使用期限
 op.issue_state AS issue_state, --交付状態
 op.ord_prescription_no  AS ord_prescription_no --処方オーダー番号
FROM
 ord_prescription AS op,
 jsonb_array_elements (prescription_detail) AS o 
WHERE
 op.facility_cd = @facilityCd
 AND
 op.pat_id = @patId
 AND op.is_del=''0''
 -- and (op.ord_prescription_no in (@ordPrescriptionNos)  or 0 in (@ordPrescriptionNos))
 and op.ord_prescription_no = @ordPrescriptionNo
 order by op asc ,type asc', db_class = 2, detail = '[{"preview": "123456", "can_calc": "0", "data_code": "Rp", "data_name": "RP番号", "data_type": "string", "conv_table": [], "data_class": "処方詳細", "field_name": "rp", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "薬剤１", "can_calc": "0", "data_code": "R", "data_name": "薬剤名称", "data_type": "string", "conv_table": [], "data_class": "処方詳細", "field_name": "r", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "内服", "can_calc": "0", "data_code": "type", "data_name": "タグ", "data_type": "string", "conv_table": [{"code": "1", "disp": "薬剤", "item": "薬剤"}, {"code": "2", "disp": "内服", "item": "内服"}, {"code": "3", "disp": "外用", "item": "外用"}, {"code": "4", "disp": "頓服内服", "item": "頓服内服"}, {"code": "5", "disp": "頓服外用", "item": "頓服外用"}, {"code": "6", "disp": "コメント", "item": "コメント"}, {"code": "E", "disp": "最終行", "item": "最終行"}], "data_class": "処方詳細", "field_name": "type", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "×", "can_calc": "0", "data_code": "unchg", "data_name": "unchg", "data_type": "string", "conv_table": [], "data_class": "処方詳細", "field_name": "unchg", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "薬剤名", "can_calc": "0", "data_code": "F1", "data_name": "薬剤名/用法", "data_type": "string", "conv_table": [], "data_class": "処方詳細", "field_name": "f1", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "調剤指示名", "can_calc": "0", "data_code": "F2", "data_name": "調剤指示名/用法詳細", "data_type": "string", "conv_table": [], "data_class": "処方詳細", "field_name": "f2", "disp_format": "", "data_category": "処方", "facility_table": "", "facility_filter_type": "0"}, {"preview": "舌下", "can_calc": "0", "data_code": "F3", "data_name": "部位", "data_type": "string", "c